{"type": "function", "function": {"name": "project_management_create_task", "description": "Creates a new task.", "parameters": {"type": "object", "properties": {"task_name": {"type": "string", "description": "Name of the task"}, "assigned_to_email": {"type": "string", "description": "Email address of the person assigned to the task"}, "list_name": {"type": "string", "description": "Name of the list the task belongs to. One of: 'Backlog', 'In Progress', 'In Review', 'Completed'"}, "due_date": {"type": "string", "description": "Due date of the task in YYYY-MM-DD format"}, "board": {"type": "string", "description": "Name of the board the task belongs to. One of: 'Back end', 'Front end', 'Design'"}}, "required": ["task_name", "assigned_to_email", "list_name", "due_date", "board"]}, "strict": false}}
