{"type": "function", "function": {"name": "project_management_update_task", "description": "Updates a task by ID.", "parameters": {"type": "object", "properties": {"task_id": {"type": "string", "description": "8-digit ID of the task"}, "field": {"type": "string", "description": "Field to update. Available fields are: 'task_name', 'assigned_to_email', 'list_name', 'due_date', 'board'"}, "new_value": {"type": "string", "description": "New value for the field"}}, "required": ["task_id", "field", "new_value"]}, "strict": false}}
